import prisma from ""../utils/prisma"";

async function verifyProfitLogic\(\) {
  console.log\(""======== 业绩归属与分润逻辑验证 ========\\n""\);

  // 获取已完成的预约，验证利润分配
  const completedReservations = await prisma.reservation.findMany\({
    where: { status: 3 }, // 已完成
    include: { items: true },
    orderBy: { completedAt: ""desc"" },
    take: 5
  }\);

  if \(completedReservations.length === 0\) {
    console.log\(""没有已完成的预约，无法验证""\);
    await prisma.$disconnect\(\);
    return;
  }

  for \(const r of completedReservations\) {
    console.log\(""-------------------------------------------""\);
    console.log\(""预约号:"", r.reservationNo\);
    console.log\(""客户:"", r.customerName\);
    console.log\(""总金额:"", Number\(r.totalAmount\)\);
    console.log\(""推销员ID:"", r.salespersonId, ""级别:"", r.salespersonLevel\);
    console.log\(""上级推销员ID:"", r.parentSalespersonId\);
    console.log\(""核销时间:"", r.completedAt\);

    // 获取推销员信息
    if \(r.salespersonId\) {
      const salesperson = await prisma.agent.findUnique\({
        where: { id: r.salespersonId },
        select: { name: true, type: true, parentId: true }
      }\);
      console.log\(""推销员:"", salesperson?.name, ""类型:"", salesperson?.type\);
    }

    console.log\(""\\n** 利润分配（存储值）**""\);
    console.log\(""  总代利润:"", Number\(r.masterProfit\)\);
    console.log\(""  一级利润:"", Number\(r.level1Profit\)\);
    console.log\(""  二级利润:"", Number\(r.level2Profit\)\);
    console.log\(""  是否已结算:"", r.settled\);

    // 重新计算利润进行验证
    console.log\(""\\n** 利润验证（按快照计算）**""\);
    let calcMasterProfit = 0;
    let calcLevel1Profit = 0;
    let calcLevel2Profit = 0;
    const orderSource = r.salespersonLevel || 0;

    for \(const item of r.items\) {
      const costPrice = Number\(item.snapshotCostPrice || 0\);
      const supplyPrice = Number\(item.snapshotSupplyPrice || costPrice\);
      const level1Price = item.snapshotLevel1Price ? Number\(item.snapshotLevel1Price\) : null;
      const retailPrice = Number\(item.snapshotRetailPrice || item.price\);
      const qty = item.quantity;

      console.log\(`  商品: ${item.productName} x ${qty}`\);
      console.log\(`    成本价:${costPrice} 供货价:${supplyPrice} 一级给二级价:${level1Price || ""无""} 零售价:${retailPrice}`\);

      if \(orderSource === 0\) {
        // 总代理订单
        const mp = \(retailPrice - costPrice\) * qty;
        calcMasterProfit += mp;
        console.log\(`    总代利润: \(${retailPrice}-${costPrice}\)*${qty} = ${mp}`\);
      } else if \(orderSource === 1\) {
        // 一级推销员
        const mp = \(supplyPrice - costPrice\) * qty;
        const l1p = \(retailPrice - supplyPrice\) * qty;
        calcMasterProfit += mp;
        calcLevel1Profit += l1p;
        console.log\(`    总代利润: \(${supplyPrice}-${costPrice}\)*${qty} = ${mp}`\);
        console.log\(`    一级利润: \(${retailPrice}-${supplyPrice}\)*${qty} = ${l1p}`\);
      } else if \(orderSource === 2\) {
        // 二级推销员
        const actualL1Price = level1Price || supplyPrice;
        const mp = \(supplyPrice - costPrice\) * qty;
        const l1p = \(actualL1Price - supplyPrice\) * qty;
        const l2p = \(retailPrice - actualL1Price\) * qty;
        calcMasterProfit += mp;
        calcLevel1Profit += l1p;
        calcLevel2Profit += l2p;
        console.log\(`    总代利润: \(${supplyPrice}-${costPrice}\)*${qty} = ${mp}`\);
        console.log\(`    一级利润: \(${actualL1Price}-${supplyPrice}\)*${qty} = ${l1p}`\);
        console.log\(`    二级利润: \(${retailPrice}-${actualL1Price}\)*${qty} = ${l2p}`\);
      }
    }

    // 取整（向下）
    calcMasterProfit = Math.floor\(calcMasterProfit * 100\) / 100;
    calcLevel1Profit = Math.floor\(calcLevel1Profit * 100\) / 100;
    calcLevel2Profit = Math.floor\(calcLevel2Profit * 100\) / 100;

    console.log\(""\\n** 计算结果对比 **""\);
    console.log\(`  总代利润: 存储=${Number\(r.masterProfit\)} 计算=${calcMasterProfit} ${Number\(r.masterProfit\) === calcMasterProfit ? ""✓"" : ""✗\(可能扣除了赠品成本\)""}`\);
    console.log\(`  一级利润: 存储=${Number\(r.level1Profit\)} 计算=${calcLevel1Profit} ${Number\(r.level1Profit\) === calcLevel1Profit ? ""✓"" : ""✗""}`\);
    console.log\(`  二级利润: 存储=${Number\(r.level2Profit\)} 计算=${calcLevel2Profit} ${Number\(r.level2Profit\) === calcLevel2Profit ? ""✓"" : ""✗""}`\);

    // 检查资金流水
    if \(r.settled\) {
      const fundFlows = await prisma.fundFlow.findMany\({
        where: {
          relatedId: r.id,
          relatedType: ""RESERVATION"",
          type: ""PROFIT""
        }
      }\);
      console.log\(""\\n** 资金流水记录 **""\);
      for \(const ff of fundFlows\) {
        const agent = await prisma.agent.findUnique\({
          where: { id: ff.agentId },
          select: { name: true, type: true }
        }\);
        console.log\(`  ${agent?.name}\(${agent?.type}\): +${Number\(ff.amount\)} 余额:${Number\(ff.beforeBalance\)}->${Number\(ff.afterBalance\)}`\);
      }
      if \(fundFlows.length === 0\) {
        console.log\(""  \(无流水记录\)""\);
      }
    }
  }

  // 检查推销员余额
  console.log\(""\\n\\n======== 推销员余额汇总 ========""\);
  const agents = await prisma.agent.findMany\({
    where: { 
      OR: [
        { type: ""LEVEL1"" },
        { type: ""LEVEL2"" },
        { isMaster: true }
      ]
    },
    select: { id: true, name: true, type: true, isMaster: true, balance: true }
  }\);

  for \(const a of agents\) {
    const label = a.isMaster ? ""总代理"" : a.type;
    console.log\(`${a.name}\(${label}\): 余额 ¥${Number\(a.balance\)}`\);
  }

  await prisma.$disconnect\(\);
}

verifyProfitLogic\(\).catch\(console.error\);
EOF
npx ts-node src/scripts/verify_profit.ts')

